import app from 'flarum/admin/app';
import m from 'mithril';
/** The admin's looks, loaded once for the whole settings page (a handful of rows). */
const state = {
  loading: false,
  loaded: false
};
export function loadLooks() {
  if (state.loading || state.loaded) return;
  state.loading = true;
  app.store.find('fanfare-looks').then(() => {
    state.loaded = true;
  }).finally(() => {
    state.loading = false;
    m.redraw();
  });
}
export const looksLoaded = () => state.loaded;
export const lookFor = occasion => app.store.all('fanfare-looks').find(look => look.occasion() === occasion);