import app from 'flarum/admin/app';
import m from 'mithril';
import FormModal from 'flarum/common/components/FormModal';
import Button from 'flarum/common/components/Button';
import Select from 'flarum/common/components/Select';
import Stream from 'flarum/common/utils/Stream';
import extractText from 'flarum/common/utils/extractText';
import { lookFor } from './looks';
const NS = 'ernestdefoe-fanfare';
const t = (key, params = {}) => app.translator.trans(`${NS}.admin.looks.${key}`, params);
/** Plain text, for option labels and attributes. */
const tx = (key, params = {}) => extractText(t(key, params));

/** Fanfare's centrepieces a look can borrow (one per drawing: the two Eids and Thanksgivings share theirs). */
const SCENES = ['birthday', 'anniversary', 'forum', 'newyear', 'christmas', 'thanksgiving', 'halloween', 'lunar', 'diwali', 'eidfitr', 'hanukkah', 'course', 'trophy'];
const SAME = {
  eidadha: 'eidfitr',
  thanksgiving_ca: 'thanksgiving'
};
const TUNES = ['birthday', 'christmas', 'auld', 'chime', 'fanfare', 'spooky'];
const EFFECTS = ['confetti', 'snow', 'fireworks', 'lanterns', 'leaves'];
/**
 * Customize one occasion: its greeting, artwork, how it comes in, its effect
 * and its sound. Pictures and sounds upload as soon as they're chosen (the
 * look is made first if it doesn't exist yet); Reset deletes the look.
 */
export default class LookModal extends FormModal {
  heading = Stream('');
  subtitle = Stream('');
  art = Stream('');
  emoji = Stream('');
  animation = Stream('rise');
  effect = Stream('');
  sound = Stream('');
  uploading = null;
  oninit(vnode) {
    super.oninit(vnode);
    this.look = lookFor(this.attrs.occasion);
    const look = this.look;
    if (!look) return;
    this.heading(look.title() || '');
    this.subtitle(look.subtitle() || '');
    this.art(look.art() || '');
    this.emoji(look.emoji() || '');
    this.animation(look.animation() || 'rise');
    this.effect(look.effect() || '');
    this.sound(look.sound() || '');
  }
  className() {
    return 'FanfareLookModal Modal--medium';
  }
  title() {
    return t('title', {
      name: this.attrs.label
    });
  }
  content() {
    return m("div", {
      className: "Modal-body"
    }, m("div", {
      className: "Form"
    }, this.textFields(), this.artFields(), m("div", {
      className: "Form-group"
    }, m("label", null, t('animation')), m(Select, {
      value: this.animation(),
      options: this.options('animation_', ['rise', 'pop', 'float', 'none']),
      onchange: this.animation
    })), m("div", {
      className: "Form-group"
    }, m("label", null, t('effect')), m(Select, {
      value: this.effect(),
      options: {
        '': tx('own_effect'),
        none: tx('no_effect'),
        ...this.options('effect_', EFFECTS)
      },
      onchange: this.effect
    })), this.soundFields(), this.buttons()));
  }
  textFields() {
    return [m("div", {
      className: "Form-group"
    }, m("label", {
      for: "FanfareLook-title"
    }, t('title_label')), m("input", {
      id: "FanfareLook-title",
      className: "FormControl",
      maxlength: 120,
      placeholder: tx('own_text'),
      bidi: this.heading
    })), m("div", {
      className: "Form-group"
    }, m("label", {
      for: "FanfareLook-subtitle"
    }, t('subtitle')), m("input", {
      id: "FanfareLook-subtitle",
      className: "FormControl",
      maxlength: 160,
      placeholder: tx('own_text'),
      bidi: this.subtitle
    }), m("p", {
      className: "helpText"
    }, t('text_help', {
      name: '{name}',
      forum: '{forum}'
    })))];
  }
  artFields() {
    const own = SAME[this.attrs.occasion] || this.attrs.occasion;
    const scenes = Object.fromEntries(SCENES.filter(id => id !== own).map(id => ['scene:' + id, tx('scene_option', {
      name: tx('scenes.' + id)
    })]));
    const image = this.look?.imageUrl();
    return m("div", {
      className: "Form-group"
    }, m("label", null, t('art')), m(Select, {
      value: this.art(),
      options: {
        '': tx('own_art'),
        emoji: tx('art_emoji'),
        image: tx('art_image'),
        ...scenes
      },
      onchange: this.art
    }), this.art() === 'emoji' ? m("input", {
      className: "FormControl FanfareLook-emoji",
      maxlength: 16,
      "aria-label": tx('emoji'),
      placeholder: "\uD83C\uDF89",
      bidi: this.emoji
    }) : null, this.art() === 'image' ? m("div", {
      className: "FanfareLook-file"
    }, image ? m("img", {
      className: "FanfareLook-thumb",
      src: image,
      alt: tx('current_image')
    }) : null, this.fileInput('image', 'image/png,image/jpeg,image/webp', 'image_help')) : null);
  }
  soundFields() {
    const url = this.look?.soundUrl();
    return m("div", {
      className: "Form-group"
    }, m("label", null, t('sound')), m(Select, {
      value: this.sound(),
      options: {
        '': tx('own_sound'),
        none: tx('no_sound'),
        ...this.options('tune_', TUNES),
        upload: tx('sound_upload')
      },
      onchange: this.sound
    }), this.sound() === 'upload' ? m("div", {
      className: "FanfareLook-file"
    }, url ? m("audio", {
      className: "FanfareLook-audio",
      controls: true,
      preload: "none",
      src: url,
      "aria-label": tx('current_sound')
    }) : null, this.fileInput('sound', 'audio/mpeg,audio/ogg,.mp3,.ogg', 'sound_help')) : null);
  }
  fileInput(kind, accept, help) {
    return m("div", {
      className: "FanfareLook-upload"
    }, m("input", {
      type: "file",
      className: "FormControl",
      accept: accept,
      "aria-label": tx(kind === 'image' ? 'choose_image' : 'choose_sound'),
      disabled: !!this.uploading,
      onchange: e => {
        const input = e.target;
        const file = input.files?.[0];
        if (file) this.upload(kind, file).then(() => input.value = '');
      }
    }), m("p", {
      className: "helpText"
    }, this.uploading === kind ? t('uploading') : t(help)));
  }
  buttons() {
    return m("div", {
      className: "Form-group Form-controls FanfareLook-buttons"
    }, m(Button, {
      type: "submit",
      className: "Button Button--primary",
      loading: this.loading,
      disabled: !!this.uploading
    }, t('save')), this.look ? m(Button, {
      className: "Button",
      icon: "fas fa-rotate-left",
      onclick: () => this.reset(),
      disabled: this.loading
    }, t('reset')) : null, m("a", {
      className: "Button Button--flat",
      href: `${app.forum.attribute('baseUrl')}/?fanfare=${this.attrs.occasion === 'trophy' ? 'milestone' : this.attrs.occasion}`,
      target: "_blank",
      rel: "noopener"
    }, m("i", {
      className: "fas fa-eye",
      "aria-hidden": "true"
    }), " ", t('preview')));
  }

  /** Options keyed by the value itself (never integer-like, so their order holds). */
  options(prefix, values) {
    return Object.fromEntries(values.map(v => [v, tx(prefix + v)]));
  }
  values() {
    return {
      title: this.heading().trim() || null,
      subtitle: this.subtitle().trim() || null,
      art: this.art(),
      emoji: this.emoji().trim() || null,
      animation: this.animation(),
      effect: this.effect(),
      sound: this.sound()
    };
  }

  /** The look, saved with what the form says now; made first if this occasion has none yet. */
  save() {
    const look = this.look || app.store.createRecord('fanfare-looks');
    const attrs = this.look ? this.values() : {
      occasion: this.attrs.occasion,
      ...this.values()
    };
    // A new record comes back as the store's own copy, with its id.
    return look.save(attrs).then(saved => this.look = saved);
  }
  onsubmit(e) {
    e.preventDefault();
    this.loading = true;
    this.save().then(() => {
      this.hide();
      app.alerts.show({
        type: 'success'
      }, t('saved'));
    }).catch(() => {
      // Core's request handler has shown what went wrong; the form stays open to fix it.
      this.loading = false;
      m.redraw();
    });
  }

  /** A picture or a sound, uploaded the moment it's chosen. The server sets the art or sound to it. */
  upload(kind, file) {
    this.uploading = kind;
    const body = new FormData();
    body.append('file', file);
    return this.save().then(look => app.request({
      method: 'POST',
      url: `${app.forum.attribute('apiUrl')}/fanfare-looks/${look.id()}/${kind}`,
      serialize: raw => raw,
      body
    }).then(res => {
      look.pushAttributes(kind === 'image' ? {
        art: 'image',
        imageUrl: res.url
      } : {
        sound: 'upload',
        soundUrl: res.url
      });
      if (kind === 'image') this.art('image');else this.sound('upload');
    })).catch(() => {
      // Core's request handler has shown the server's reason (type or size).
    }).finally(() => {
      this.uploading = null;
      m.redraw();
    });
  }
  reset() {
    if (!this.look) return;
    this.loading = true;
    this.look.delete().then(() => {
      this.hide();
      app.alerts.show({
        type: 'success'
      }, t('reset_done'));
    }).catch(() => {
      // Core's request handler has shown what went wrong.
      this.loading = false;
      m.redraw();
    });
  }
}