import app from 'flarum/admin/app';
import Component from 'flarum/common/Component';
import Button from 'flarum/common/components/Button';
import LookModal from './LookModal';
import { loadLooks, lookFor, looksLoaded } from './looks';
const NS = 'ernestdefoe-fanfare';
const t = key => app.translator.trans(`${NS}.admin.looks.${key}`);
/** Opens the Customize dialog for one occasion; marked when the occasion has a look. */
export default class CustomizeButton extends Component {
  oninit(vnode) {
    super.oninit(vnode);
    loadLooks();
  }
  view() {
    const {
      occasion,
      label
    } = this.attrs;
    const customized = !!lookFor(occasion);
    return m(Button, {
      className: 'Button Button--flat FanfareLook-customize' + (customized ? ' is-customized' : ''),
      icon: "fas fa-palette",
      disabled: !looksLoaded(),
      onclick: () => app.modal.show(LookModal, {
        occasion,
        label
      })
    }, t('customize'), customized ? m("span", {
      className: "FanfareLook-mark"
    }, t('customized')) : null);
  }
}