import Model from 'flarum/common/Model';

/** An admin's look for one occasion (fanfare-looks). Empty fields keep Fanfare's own. */
export default class Look extends Model {
  occasion() {
    return Model.attribute('occasion').call(this);
  }
  title() {
    return Model.attribute('title').call(this);
  }
  subtitle() {
    return Model.attribute('subtitle').call(this);
  }
  art() {
    return Model.attribute('art').call(this);
  }
  emoji() {
    return Model.attribute('emoji').call(this);
  }
  animation() {
    return Model.attribute('animation').call(this);
  }
  effect() {
    return Model.attribute('effect').call(this);
  }
  sound() {
    return Model.attribute('sound').call(this);
  }
  imageUrl() {
    return Model.attribute('imageUrl').call(this);
  }
  soundUrl() {
    return Model.attribute('soundUrl').call(this);
  }
}
flarum.reg.add('ernestdefoe-fanfare', 'admin/models/Look', Look);